#include "tangra_fc/usb_configuration.hpp"
#include <cassert>
#include <iostream>
#include <optional>
#include <string>
#include <vector>
using namespace tangra::fc;
struct MemStorage final:IParameterStorage{std::optional<std::string>bytes;bool save(const std::string&s)override{bytes=s;return true;}std::optional<std::string>load()override{return bytes;}};
struct LoopTransport final:IUsbConfigurationTransport{std::vector<std::string>in,out;std::optional<std::string>read_request()override{if(in.empty())return std::nullopt;auto s=in.front();in.erase(in.begin());return s;}void write_response(const std::string&s)override{out.push_back(s);}};
int main(){auto schema=make_fc_configuration_schema();assert(schema.size()>=35);auto defs=configuration_parameter_defs(schema);ParameterStore store(1,defs);MemStorage storage;FirmwareIdentity id{"TANGRA_FC","1.0.0","host-test",1,1};FcConfigurationService service(id,store,storage,schema);assert(service.validate().valid);assert(service.get("vehicle.profile").value()==0);assert(service.get("motor.count").value()==4);std::string err;assert(service.set("pid.roll.p",2.5,&err));assert(!service.set("pid.roll.p",50,&err));assert(!service.set("motor.count",3,&err)&&err=="motor.count:profile_dependency");assert(!service.set("vehicle.profile",1,&err)&&err=="vehicle.profile:not_implemented");assert(!service.set("watchdog.deadline_ms",100,&err)&&err=="watchdog.deadline_ms:must_cover_command_timeout");assert(service.save(&err)&&storage.bytes);assert(service.set("pid.roll.p",3,&err));assert(store.restore(storage)&&service.get("pid.roll.p").value()==2.5);auto exported=service.export_parameters();assert(service.set("pid.roll.p",4,&err));assert(service.import_parameters(exported,&err)&&service.get("pid.roll.p").value()==2.5);assert(service.defaults(&err)&&service.get("pid.roll.p").value()==1&&service.get("vehicle.profile").value()==0);UsbConfigurationProtocol p(service);assert(p.handle("IDENTITY").find("OK IDENTITY TANGRA_FC 1.0.0 host-test 1 1")==0);assert(p.handle("SCHEMA COUNT").find("OK SCHEMA COUNT ")==0);assert(p.handle("SCHEMA 0").find("vehicle.profile")!=std::string::npos);assert(p.handle("SET nav.max_speed_mps 7.5")=="OK SET nav.max_speed_mps");assert(p.handle("SET nav.max_speed_mps 100")=="ERR SET out_of_range_or_invalid");assert(p.handle("SET motor.count 3")=="ERR SET motor.count:profile_dependency");assert(p.handle("VALIDATE")=="OK VALIDATE");assert(p.handle("SAVE")=="OK SAVE");auto ex=p.handle("EXPORT");auto hex=ex.substr(std::string("OK EXPORT ").size());assert(p.handle("SET pid.yaw.p 2.2")=="OK SET pid.yaw.p");assert(p.handle("IMPORT "+hex)=="OK IMPORT");LoopTransport tr;tr.in={"GET vehicle.profile","DEFAULTS"};UsbConfigurationSession session(p,tr);assert(session.poll_once()&&session.poll_once()&&!session.poll_once()&&tr.out.size()==2);ParameterStore legacy(1,{{"kp",1,0,10}});MemStorage ls;assert(legacy.set("kp",3)&&legacy.persist(ls,"legacy"));ParameterStore lr(1,{{"kp",1,0,10}});assert(lr.restore(ls)&&lr.get("kp")==3);std::cout<<"PASS: USB configuration/schema/profile/persistence/backward compatibility\n";}
